function baseReport(spec, status) {
  return {
    schema: L.SCHEMA, runId: spec.runId || null, status, version: spec.version || null, javaRelease: spec.javaRelease || null,
    startedAt: new Date().toISOString(), finishedAt: null, checks: emptyChecks(requiredFor(spec || {})),
    timings: {}, bootMs: null, doneReportedSec: null, peakRssKb: null, artifacts: [], engine: null, notes: [], overall: "incomplete",
  };
}
function finish(rep) {
  rep.finishedAt = new Date().toISOString();
  rep.overall = rep.status === "completed" ? L.overallOf(rep.checks) : "incomplete";
  return rep;
}

// ------------------------------------------------------------------ toolchains (host network, lock held) ----
async function download(url, dest, expectSha) {
  const r = await fetch(url, { redirect: "follow" });
  if (!r.ok) throw new Error(`download ${url}: HTTP ${r.status}`);
  const tmp = dest + ".part";
  fs.writeFileSync(tmp, Buffer.from(await r.arrayBuffer()));
  const got = sha256File(tmp);
  if (got !== expectSha) { fs.rmSync(tmp, { force: true }); throw new Error(`sha256 mismatch for ${url}: got ${got}, want ${expectSha}`); }
  fs.renameSync(tmp, dest);
}

async function ensureJdk(release) {
  const pin = JDKS[release];
  if (!pin) throw new Error(`no pinned JDK for release ${release}`);
  const dir = path.join(TF_ROOT, "jdk", String(release));
  const ok = path.join(dir, ".nxeon-ok");
  if (fs.existsSync(ok) && fs.readFileSync(ok, "utf8").trim() === pin.sha256 && fs.existsSync(path.join(dir, "bin/java"))) {
    return { home: dir, ...pin, fetched: false };
  }
  const dl = path.join(TF_ROOT, "dl");
  fs.mkdirSync(dl, { recursive: true });
  const tgz = path.join(dl, `${pin.sha256}.tar.gz`);
  if (!fs.existsSync(tgz) || sha256File(tgz) !== pin.sha256) { log(`downloading ${pin.release}`); await download(pin.url, tgz, pin.sha256); }
  fs.mkdirSync(path.join(TF_ROOT, "jdk"), { recursive: true });
  const tmp = fs.mkdtempSync(path.join(TF_ROOT, "jdk", `.x-${release}-`));
  const x = spawnSync("tar", ["-xzf", tgz, "-C", tmp], { stdio: "inherit" });
  if (x.status !== 0) throw new Error("tar failed");
  const inner = path.join(tmp, pin.release);
  if (!fs.existsSync(path.join(inner, "bin/java"))) throw new Error(`unexpected JDK layout in ${tgz}`);
  fs.rmSync(dir, { recursive: true, force: true });
  fs.renameSync(inner, dir);
  fs.rmSync(tmp, { recursive: true, force: true });
  fs.writeFileSync(ok, pin.sha256 + "\n");
  return { home: dir, ...pin, fetched: true };
}

function jdkVersion(home) {
  try { return /JAVA_VERSION="([^"]+)"/.exec(fs.readFileSync(path.join(home, "release"), "utf8"))[1]; } catch { return null; }
}

/** Paper server jar cached by sha256 and pre-patched (paperclip patch-only) so runs need no network. */
async function ensurePaper(version, build, sha) {
  const dir = path.join(TF_ROOT, "paper", sha);
  const jar = path.join(dir, "paper.jar");
  const meta = path.join(dir, "fill.json");
  const warmed = path.join(dir, ".nxeon-warmed");
  let fill = null;
  if (!fs.existsSync(jar) || sha256File(jar) !== sha) {
    fs.mkdirSync(dir, { recursive: true });
    const api = `https://fill.papermc.io/v3/projects/paper/versions/${encodeURIComponent(version)}/builds/${build}`;
    const r = await fetch(api, { headers: { "User-Agent": "nxeon-testflight/1 (build host)" } });
    if (!r.ok) throw new Error(`Fill API ${api}: HTTP ${r.status}`);
    fill = await r.json();
    const d = fill.downloads && fill.downloads["server:default"];
    if (!d || !d.checksums || d.checksums.sha256 !== sha) throw new Error(`Fill reports sha256 ${d && d.checksums && d.checksums.sha256} for ${version} build ${build}; registry pin is ${sha}`);
    log(`downloading Paper ${version} build ${build} (${fill.channel})`);
    await download(d.url, jar, sha);
    fs.writeFileSync(meta, JSON.stringify({ id: fill.id, channel: fill.channel, time: fill.time, name: d.name, url: d.url, sha256: sha }, null, 1));
  } else if (fs.existsSync(meta)) fill = JSON.parse(fs.readFileSync(meta, "utf8"));
  return { dir, jar, warmed, fill };
}

function warmPaper(p, javaHome) {
  if (fs.existsSync(p.warmed)) return { warmed: false };
  log("pre-patching Paper (paperclip patch-only, one-off per jar)");
  const t0 = now();
  const r = spawnSync("nice", ["-n", "10", path.join(javaHome, "bin/java"), "-Xmx512m", "-Dpaperclip.patchonly=true", `-DbundlerRepoDir=${p.dir}`, "-jar", p.jar],
    { cwd: p.dir, encoding: "utf8", timeout: 300000, killSignal: "SIGKILL" });
  if (r.status !== 0) throw new Error(`paperclip patch-only failed (${r.status}): ${clip((r.stdout || "") + (r.stderr || ""), 600)}`);
  fs.writeFileSync(p.warmed, new Date().toISOString() + "\n");
  return { warmed: true, ms: now() - t0 };
}

/**
 * The pinned playtest bot (Mineflayer) installed from the committed lockfile with `npm ci --ignore-scripts` (npm
 * verifies every package's integrity hash). Cached per lockfile sha256 under TF_ROOT/bot/<sha>/; root-owned, read-only
 * to the bot's uid. Host network, lock held (same as JDK / Paper downloads).
 */
function ensureBot() {
  const lockFile = path.join(__dirname, "bot-package-lock.json"), pkgFile = path.join(__dirname, "bot-package.json");
  if (!fs.existsSync(lockFile) || !fs.existsSync(pkgFile)) throw new Error("bot-package.json / bot-package-lock.json missing next to the runner");
  const lockSha = sha256File(lockFile);
  const dir = path.join(TF_ROOT, "bot", lockSha);
  const ok = path.join(dir, ".nxeon-ok");
  const want = JSON.parse(fs.readFileSync(pkgFile, "utf8")).dependencies.mineflayer;
  const check = () => { try { return JSON.parse(fs.readFileSync(path.join(dir, "node_modules/mineflayer/package.json"), "utf8")).version === want; } catch { return false; } };
  if (fs.existsSync(ok) && check()) return { dir, modulesDir: path.join(dir, "node_modules"), lockSha, installed: false };
  fs.mkdirSync(path.join(TF_ROOT, "bot"), { recursive: true });
  const tmp = fs.mkdtempSync(path.join(TF_ROOT, "bot", ".x-"));
  fs.copyFileSync(pkgFile, path.join(tmp, "package.json"));
  fs.copyFileSync(lockFile, path.join(tmp, "package-lock.json"));
  const t0 = now();
  const r = spawnSync("nice", ["-n", "10", "npm", "ci", "--ignore-scripts", "--no-audit", "--no-fund", "--omit=dev", "--cache", path.join(TF_ROOT, "bot", ".npm-cache")],
    { cwd: tmp, encoding: "utf8", timeout: 300000, killSignal: "SIGKILL" });
  if (r.status !== 0) { fs.rmSync(tmp, { recursive: true, force: true }); throw new Error(`npm ci for the playtest bot failed (${r.status}): ${clip((r.stderr || "") + (r.stdout || ""), 500)}`); }
  fs.chmodSync(tmp, 0o755); // mkdtemp makes it 0700; the bot runs as uid 65534 and must read it
  fs.rmSync(dir, { recursive: true, force: true });
  fs.renameSync(tmp, dir);
  if (!check()) throw new Error(`playtest bot install has the wrong mineflayer version (want ${want})`);
  fs.writeFileSync(ok, lockSha + "\n");
  return { dir, modulesDir: path.join(dir, "node_modules"), lockSha, installed: true, ms: now() - t0 };
}

// ------------------------------------------------------------------ leak scan (by exact marker) ----
function procsWithMarker(marker) {
  const out = [];
  for (const d of fs.readdirSync("/proc")) {
    if (!/^\d+$/.test(d) || Number(d) === process.pid) continue;
    let cmd;
    try { cmd = fs.readFileSync(`/proc/${d}/cmdline`, "utf8"); } catch { continue; }
    if (cmd.split("\0").includes(marker)) out.push({ pid: Number(d), cmd: clip(cmd.replace(/\0/g, " "), 200) });
  }
  return out;
}
function killExact(pid, marker) {
  // Re-read the cmdline right before the kill so a recycled PID is never hit.
  try {
    const cmd = fs.readFileSync(`/proc/${pid}/cmdline`, "utf8");

    const cmd = fs.readFileSync(`/proc/${pid}/cmdline`, "utf8");
    if (!cmd.split("\0").includes(marker)) return false;
    process.kill(pid, "SIGKILL");
    return true;
  } catch { return false; }
}

// ------------------------------------------------------------------ stage: run (no lock yet) ----
function stageRun(specPath) {
  let spec;
  try { spec = JSON.parse(fs.readFileSync(specPath, "utf8")); } catch (e) { process.stdout.write(JSON.stringify({ error: `bad spec: ${e.message}` }) + "\n"); return 2; }
  const errs = L.validateResolvedSpec(spec, TF_ROOT);
  if (errs.length) { process.stdout.write(JSON.stringify({ error: "invalid spec", problems: errs }) + "\n"); return 2; }
  fs.mkdirSync(TF_ROOT, { recursive: true });
  const r = spawnSync("flock", ["-n", "-E", String(BUSY_EXIT), LOCK, process.execPath, __filename, "locked", specPath],
    { stdio: ["ignore", "inherit", "inherit"], timeout: ((spec.timeouts && spec.timeouts.totalSec) || 420) * 1000 + 360000, killSignal: "SIGKILL" });
  if (r.status === BUSY_EXIT) {
    const rep = baseReport(spec, "busy");
    rep.notes.push("Another Test Flight holds the node-2 lock; nothing ran. Retry later.");
    process.stdout.write(JSON.stringify(finish(rep)) + "\n");
    return BUSY_EXIT;
  }
  return r.status == null ? 1 : r.status;
}

// ------------------------------------------------------------------ stage: locked (host netns, lock held) ----
async function stageLocked(specPath) {
  const spec = JSON.parse(fs.readFileSync(specPath, "utf8"));
  const rep = baseReport(spec, "error");
  const t0 = now();
  const marker = `-Dnxeon.testflight.run=${spec.runId}`;
  const runDir = path.join(TF_ROOT, "runs", spec.runId);
  try {
    if (fs.existsSync(runDir)) throw new Error(`run dir ${runDir} already exists (runId reused?)`);
    const jdk = await ensureJdk(spec.javaRelease);
    const paper = await ensurePaper(spec.version, spec.paper.build, spec.paper.sha256);
    const warm = warmPaper(paper, jdk.home);
    rep.timings.toolchainMs = now() - t0;
    if (warm.warmed) rep.notes.push(`Paper pre-patched this run (${warm.ms} ms, one-off per jar; not counted in bootMs).`);

    // Artifacts: verify hashes, read descriptors.
    const plugins = [];
    for (const p of spec.plugins || []) {
      const buf = fs.readFileSync(p.path);
      const sha = crypto.createHash("sha256").update(buf).digest("hex");
      if (p.sha256 && p.sha256 !== sha) throw new Error(`plugin ${path.basename(p.path)}: sha256 ${sha} does not match the spec ${p.sha256}`);
      let meta;
      try { meta = L.pluginMeta(buf); } catch (e) { meta = { descriptor: null, name: null, error: e.message }; }
      plugins.push({ path: p.path, file: path.basename(p.path), sha256: sha, ...meta });
      rep.artifacts.push({ kind: "plugin", file: path.basename(p.path), sha256: sha, pluginName: meta.name, apiVersion: meta.apiVersion || null, descriptor: meta.descriptor });
    }
    for (const d of spec.datapacks || []) {
      const st = fs.statSync(d.path);
      rep.artifacts.push({ kind: "datapack", name: d.name, sha256: st.isFile() ? sha256File(d.path) : null, directory: st.isDirectory() });
    }
    if (spec.resourcePack) rep.artifacts.push({ kind: "resourcePack", url: spec.resourcePack.url, sha1: spec.resourcePack.sha1 || null, exercised: false });

    rep.engine = {
      runner: RUNNER_VERSION, runnerSha256: selfHash(), node: process.version, host: os.hostname(), kernel: os.release(),
      jdk: { release: spec.javaRelease, version: jdkVersion(jdk.home), dist: jdk.release, sha256: jdk.sha256 },
      paper: { version: spec.version, build: spec.paper.build, sha256: spec.paper.sha256, channel: paper.fill ? paper.fill.channel : null },
      isolation: { netns: "private (loopback only)", uid: RUN_UID, noNewPrivs: true, nice: 10, activeProcessorCount: 2 },
    };

    // Fresh run dir owned by the unprivileged uid.
    fs.mkdirSync(path.join(runDir, "plugins/bStats"), { recursive: true });
    fs.mkdirSync(path.join(runDir, "tmp"));
    fs.writeFileSync(path.join(runDir, "plugins/bStats/config.txt"), "enabled=false\n");
    for (const p of plugins) fs.copyFileSync(p.path, path.join(runDir, "plugins", p.file));
    if ((spec.datapacks || []).length) {
      const dp = path.join(runDir, "world/datapacks");
      fs.mkdirSync(dp, { recursive: true });
      for (const d of spec.datapacks) {
        const st = fs.statSync(d.path);
        if (st.isDirectory()) fs.cpSync(d.path, path.join(dp, d.name), { recursive: true });
        else fs.copyFileSync(d.path, path.join(dp, d.name.endsWith(".zip") ? d.name : d.name + ".zip"));
      }
    }
    for (const sd of spec.seeds || []) {
      const r = placeSeed(runDir, sd);
      rep.artifacts.push({ kind: "seed", from: sd.from, to: sd.to, files: r.files, bytes: r.bytes, sha256: r.sha256 });
    }
    for (const f of spec.files || []) writeServerFile(runDir, f);
    let bot = null, botError = null;
    const stressBot = !!(spec.stress && spec.stress.bot !== false && PT.BOT_VERSIONS.includes(spec.version));
    if (spec.playtest || stressBot) {
      try {
        bot = ensureBot();
        if (bot.installed) rep.notes.push(`playtest bot installed from the pinned lockfile (${bot.ms} ms, one-off per lockfile)`);
        rep.engine.bot = { lockSha256: bot.lockSha, versions: PT.BOT_VERSIONS };
      } catch (e) { botError = clip(e.message, 400); }
      if (spec.playtest && spec.playtest.op) {
        const name = spec.playtest.username || PT.DEFAULTS.username;
        fs.writeFileSync(path.join(runDir, "ops.json"), JSON.stringify([{ uuid: PT.offlineUuid(name), name, level: 4, bypassesPlayerLimit: false }], null, 1));
        rep.notes.push(`playtest: ${name} is a server operator (ops.json, level 4)`);
      }
    }
    if ((spec.files || []).length) rep.notes.push(`placed ${spec.files.length} server file(s): ${spec.files.map((f) => f.path).join(", ")}`);
    spawnSync("chown", ["-R", `${RUN_UID}:${RUN_UID}`, runDir]);

    const ctx = { spec, plugins, runDir, marker, javaHome: jdk.home, paperDir: paper.dir, paperJar: paper.jar, out: path.join(runDir, ".inner-report.json"),
      bot: bot ? { modulesDir: bot.modulesDir, lockSha: bot.lockSha } : null, botError };
    const ctxPath = path.join(TF_ROOT, "runs", `${spec.runId}.ctx.json`);
    fs.writeFileSync(ctxPath, JSON.stringify(ctx));

    const totalMs = ((spec.timeouts && spec.timeouts.totalSec) || 420) * 1000;
    const ti = now();
    const r = spawnSync("unshare", ["--net", "--", "sh", "-c", 'ip link set lo up && exec "$0" "$@"', process.execPath, __filename, "inner", ctxPath],
      { stdio: ["ignore", "inherit", "inherit"], timeout: totalMs + 60000, killSignal: "SIGKILL" });
    rep.timings.innerMs = now() - ti;
    let inner = null;
    try { inner = JSON.parse(fs.readFileSync(ctx.out, "utf8")); } catch { /* inner died before writing */ }
    if (inner) {
      Object.assign(rep, { checks: inner.checks, bootMs: inner.bootMs, doneReportedSec: inner.doneReportedSec, peakRssKb: inner.peakRssKb });
      if (inner.playtest) rep.playtest = inner.playtest;
      if (inner.stress) rep.stress = inner.stress;
      if (inner.worldgen) rep.worldgen = inner.worldgen;
      Object.assign(rep.timings, inner.timings);
      rep.notes.push(...inner.notes);
      rep.status = "completed";
    } else {
      rep.notes.push(`inner stage produced no report (exit ${r.status}, signal ${r.signal}${r.error ? ", " + r.error.message : ""})`);
    }
    fs.rmSync(ctxPath, { force: true });
  } catch (e) {
    rep.notes.push(`runner error: ${clip(e.message, 600)}`);
  }

  // Host-side leak check (runs even after an error): any process still carrying this run's marker is a leak.
  const leakCheck = rep.checks.find((c) => c.id === "no_leaks");
  const tl = now();
  const leaked = procsWithMarker(marker);
  for (const p of leaked) leakCheck.evidence.push(`host: leaked pid ${p.pid} (${p.cmd}) -> SIGKILL ${killExact(p.pid, marker) ? "sent" : "skipped (gone/recycled)"}`);
  if (leaked.length) await sleep(500);
  const hostPorts = new Set();
  for (const f of ["/proc/net/tcp", "/proc/net/tcp6"]) { try { for (const p of L.listeningPorts(fs.readFileSync(f, "utf8"))) hostPorts.add(p); } catch { /* none */ } }
  const inRange = [...hostPorts].filter((p) => p >= L.PORT_RANGE.min && p <= L.PORT_RANGE.max);
  if (inRange.length) leakCheck.evidence.push(`host: listening ports in the reserved range: ${inRange.join(",")}`);
  if (leaked.length || inRange.length) leakCheck.status = "fail";
  else {
    // No pid namespace is used, so this /proc scan sees every process on the host, inside the netns or not.
    leakCheck.evidence.push(`host: no process carries ${marker}; no listening port in ${L.PORT_RANGE.min}-${L.PORT_RANGE.max}`);
    if (leakCheck.status === "not_run") leakCheck.status = "pass";
  }
  leakCheck.durationMs += now() - tl;

  if ((spec.collect || []).length && fs.existsSync(runDir)) {
    try { rep.collected = collectOut(runDir, spec); } catch (e) { rep.notes.push(`collect error: ${clip(e.message, 300)}`); }
  }
  if (!spec.keepDir) fs.rmSync(runDir, { recursive: true, force: true });
  else rep.notes.push(`run dir kept: ${runDir}`);
  rep.timings.totalMs = now() - t0;
  finish(rep);
  fs.mkdirSync(path.join(TF_ROOT, "reports"), { recursive: true });
  fs.writeFileSync(path.join(TF_ROOT, "reports", `${spec.runId}.json`), JSON.stringify(rep, null, 1));
  process.stdout.write(JSON.stringify(rep) + "\n");
  return 0;
}

/** Walk a directory without following symlinks: [{ rel, abs, size }] of regular files; throws on a symlink. */
function walkPlain(dir, rel = "", out = []) {
  for (const e of fs.readdirSync(path.join(dir, rel), { withFileTypes: true }).sort((a, b) => (a.name < b.name ? -1 : 1))) {
    const r = rel ? `${rel}/${e.name}` : e.name;
    if (e.isSymbolicLink()) throw new Error(`symlink refused: ${r}`);
    if (e.isDirectory()) walkPlain(dir, r, out);
    else if (e.isFile()) out.push({ rel: r, abs: path.join(dir, r), size: fs.statSync(path.join(dir, r)).size });
  }
  return out;
}

/** Copy TF_ROOT/seeds/<from> into runDir/<to> (seed dirs are prepared by an operator; files are hashed + reported). */
const MAX_SEED_BYTES = 256 * 1024 * 1024;
function placeSeed(runDir, sd) {
  if (!L.SEED_NAME_RE.test(sd.from) || !L.SEED_TO_RE.test(sd.to) || sd.to.split("/").includes("..")) throw new Error(`refusing seed ${sd.from} -> ${sd.to}`);
  const src = path.join(TF_ROOT, "seeds", sd.from);
  if (!fs.lstatSync(src).isDirectory()) throw new Error(`seed ${sd.from} is not a directory`);
  const files = walkPlain(src);
  const bytes = files.reduce((a, f) => a + f.size, 0);
  if (bytes > MAX_SEED_BYTES) throw new Error(`seed ${sd.from} is larger than ${MAX_SEED_BYTES} bytes`);
  const dest = path.join(runDir, sd.to);
  if (!dest.startsWith(runDir + path.sep)) throw new Error(`seed escapes the run dir: ${sd.to}`);
  const h = crypto.createHash("sha256");
  for (const f of files) {
    const d = path.join(dest, f.rel);
    fs.mkdirSync(path.dirname(d), { recursive: true });
    fs.copyFileSync(f.abs, d);
    h.update(`${sha256File(f.abs)}  ${f.rel}\n`);
  }
  return { files: files.length, bytes, sha256: h.digest("hex") };
}

/** Copy the requested server files out (or list a directory) after the stop. Never follows symlinks. */
const MAX_COLLECT_BYTES = 48 * 1024 * 1024;
function collectOut(runDir, spec) {
  const outDir = path.join(TF_ROOT, "collect", spec.runId);
  fs.mkdirSync(outDir, { recursive: true });
  const res = [];
  for (const [i, c] of (spec.collect || []).entries()) {
    if (!L.COLLECT_RE.test(c) || c.split("/").includes("..")) { res.push({ path: c, error: "refused" }); continue; }
    const abs = path.join(runDir, c.replace(/\/$/, ""));
    if (!abs.startsWith(runDir + path.sep)) { res.push({ path: c, error: "refused" }); continue; }
    let st;
    try { st = fs.lstatSync(abs); } catch { res.push({ path: c, error: "missing" }); continue; }
    if (st.isSymbolicLink()) { res.push({ path: c, error: "symlink" }); continue; }
    if (c.endsWith("/")) {
      if (!st.isDirectory()) { res.push({ path: c, error: "not a directory" }); continue; }
      let list = [];
      try { list = walkPlain(abs).map((f) => `${f.rel} ${f.size}`); } catch (e) { res.push({ path: c, error: e.message }); continue; }
      res.push({ path: c, kind: "listing", entries: list.length, listing: list.slice(0, 400) });
      continue;
    }
    if (!st.isFile()) { res.push({ path: c, error: "not a file" }); continue; }
    if (st.size > MAX_COLLECT_BYTES) { res.push({ path: c, error: `larger than ${MAX_COLLECT_BYTES} bytes` }); continue; }
    const dest = path.join(outDir, `${i}-${path.basename(abs)}`);
    fs.copyFileSync(abs, dest);
    res.push({ path: c, kind: "file", bytes: st.size, sha256: sha256File(dest), dest });
  }
  return res;
}

/** Write a spec text file under runDir (path re-validated; parent dirs and file owned by the server uid). */
function writeServerFile(runDir, f) {
  if (!L.SERVER_FILE_RE.test(f.path) || f.path.split("/").includes("..")) throw new Error(`refusing server file path ${f.path}`);
  const dest = path.join(runDir, f.path);
  if (!dest.startsWith(runDir + path.sep)) throw new Error(`server file escapes the run dir: ${f.path}`);
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  const tmp = `${dest}.tf-part`;
  fs.writeFileSync(tmp, f.content);
  fs.renameSync(tmp, dest);
  let d = path.dirname(dest);
  while (d.startsWith(runDir + path.sep)) { spawnSync("chown", [`${RUN_UID}:${RUN_UID}`, d]); d = path.dirname(d); }
  spawnSync("chown", [`${RUN_UID}:${RUN_UID}`, dest]);
  return Buffer.byteLength(f.content, "utf8");
}

// ------------------------------------------------------------------ RCON client ----
function rconConnect(port, password, timeoutMs) {
  return new Promise((resolve, reject) => {
    const sock = net.connect({ host: "127.0.0.1", port });
    let buf = Buffer.alloc(0);
    const waiters = [];
    let nextId = 100;
    const timer = setTimeout(() => { sock.destroy(); reject(new Error("rcon connect timeout")); }, timeoutMs);
    sock.on("data", (d) => {
      buf = Buffer.concat([buf, d]);
      const { packets, rest } = L.rconParse(buf);
      buf = rest;
      for (const p of packets) for (const w of waiters) w(p);
    });
    sock.on("error", (e) => { clearTimeout(timer); reject(e); });
    const request = (type, body, quietMs = 250, maxMs = timeoutMs) => new Promise((res, rej) => {
      const id = nextId++;
      let text = "", got = false, q = null;
      const done = () => { waiters.splice(waiters.indexOf(w), 1); clearTimeout(hard); clearTimeout(q); res({ id, text, got }); };
      const w = (p) => {
        if (p.id === -1 && type === 3) { waiters.splice(waiters.indexOf(w), 1); clearTimeout(hard); rej(new Error("rcon auth refused")); return; }
        if (p.id !== id) return;
        got = true; text += p.body;
        clearTimeout(q); q = setTimeout(done, type === 3 ? 0 : quietMs);
      };
