#!/usr/bin/env node
"use strict";
// Cyrus Test Flight STRESS bot (runner tf-lite-5, combat mode tf-lite-6): ONE scripted Mineflayer player that joins the
// disposable server. Mode "build" (default, CREATIVE): until its deadline it places and breaks blocks next to itself
// (real BlockPlaceEvent / BlockBreakEvent) and teleports to a new spot every few seconds (real chunk loads and player
// movement). Mode "combat" (SURVIVAL, for mob / boss / combat mods: mob AI ignores creative players, so a creative bot
// would be a false green): it gets a sword, food and resistance over RCON, the difficulty leaves peaceful, small waves
// of hostile mobs are summoned around it and it fights the nearest foe (real EntityDamageByEntityEvent, mob targeting,
// EntityDeathEvent). Started by runner.js inside the flight's
// private network namespace as uid 65534 with a heap cap and a hard timeout; talks only to 127.0.0.1. No free-form
// code. Output: "@@ST " JSON lines (one final result). Usage: node stress-bot.js <script.json> <run marker>

const fs = require("fs");
const path = require("path");
const net = require("net");
const L = require("./lib.js");
const SL = require("./stress-lib.js");

const now = () => Date.now();
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const clip = (s, n = 200) => String(s).replace(/\s+/g, " ").slice(0, n);
const emit = (o) => process.stdout.write("@@ST " + JSON.stringify(o) + "\n");
const within = (p, ms) => Promise.race([p, sleep(ms).then(() => { throw new Error(`timeout after ${ms} ms`); })]);

function rconConnect(port, password, timeoutMs) {
  return new Promise((resolve, reject) => {
    const sock = net.connect({ host: "127.0.0.1", port });
    let buf = Buffer.alloc(0), nextId = 900;
    const waiters = [];
    const timer = setTimeout(() => { sock.destroy(); reject(new Error("rcon connect timeout")); }, timeoutMs);
    sock.on("data", (d) => { buf = Buffer.concat([buf, d]); const { packets, rest } = L.rconParse(buf); buf = rest; for (const p of packets) for (const w of [...waiters]) w(p); });
    sock.on("error", (e) => { clearTimeout(timer); reject(e); });
    const request = (type, body, maxMs = timeoutMs) => new Promise((res, rej) => {
      const id = nextId++;
      let text = "", q = null, got = false;
      const done = () => { waiters.splice(waiters.indexOf(w), 1); clearTimeout(hard); res(text); };
      const w = (p) => {
        if (p.id === -1 && type === 3) { waiters.splice(waiters.indexOf(w), 1); clearTimeout(hard); rej(new Error("rcon auth refused")); return; }
        if (p.id !== id) return;
        got = true; text += p.body; clearTimeout(q); q = setTimeout(done, type === 3 ? 0 : 150);
      };
      const hard = setTimeout(() => { waiters.splice(waiters.indexOf(w), 1); clearTimeout(q); got ? res(text) : rej(new Error(`rcon timeout after ${maxMs} ms`)); }, maxMs);
      waiters.push(w);
      sock.write(L.rconPacket(id, type, body));
    });
    sock.on("connect", async () => {
      clearTimeout(timer);
      try { await request(3, password); resolve({ command: (c, ms) => request(2, c, ms), close: () => sock.destroy() }); } catch (e) { sock.destroy(); reject(e); }
    });
  });
}

async function main() {
  const script = JSON.parse(fs.readFileSync(process.argv[2], "utf8"));
  const username = "NxStress";
  const mode = SL.BOT_MODES.includes(script.mode) ? script.mode : "build";
  const result = { schema: 1, username, mode, joined: false, placed: 0, broken: 0, failed: 0, teleports: 0, notes: [], bot: { mineflayer: null } };
  if (mode === "combat") Object.assign(result, { gamemode: null, attacks: 0, hurt: 0, kills: 0, deaths: 0, summoned: 0, setupFailed: 0 });
  const deadline = now() + script.seconds * 1000;
  const guard = setTimeout(() => { result.notes.push("stress bot hard timeout"); finish(); }, script.seconds * 1000 + 40000);
  let finished = false;
  function finish() { if (finished) return; finished = true; clearTimeout(guard); emit({ ev: "result", result }); setTimeout(() => process.exit(0), 200); }

  let mineflayer, Vec3;
  try {
    mineflayer = require(path.join(script.modulesDir, "mineflayer"));
    Vec3 = require(path.join(script.modulesDir, "vec3")).Vec3;
    result.bot.mineflayer = require(path.join(script.modulesDir, "mineflayer/package.json")).version;
  } catch (e) { result.notes.push(`mineflayer not available: ${clip(e.message)}`); return finish(); }
  let rcon = null;
  try { rcon = await rconConnect(script.rconPort, script.rconPassword, 10000); } catch (e) { result.notes.push(`stress bot RCON unavailable: ${clip(e.message)}`); }

  const bot = mineflayer.createBot({ host: "127.0.0.1", port: script.port, username, version: script.version, auth: "offline", hideErrors: true, checkTimeoutInterval: 120000, logErrors: false });
  let ended = null;
  bot.on("error", (e) => result.notes.push(`bot error: ${clip(e && e.message)}`));
  bot.on("end", (reason) => { ended = ended || clip(reason || "end"); });
  bot.on("kicked", (reason) => { ended = `kicked: ${clip(typeof reason === "string" ? reason : JSON.stringify(reason))}`; });
  const joined = await new Promise((resolve) => {
    const t = setTimeout(() => resolve(false), 30000);
    bot.once("spawn", () => { clearTimeout(t); resolve(true); });
    bot.once("end", () => { clearTimeout(t); resolve(false); });
  });
  if (!joined) { result.notes.push(ended ? `could not join: ${ended}` : "did not spawn within 30 s"); try { bot.quit(); } catch { /* */ } if (rcon) rcon.close(); return finish(); }
  result.joined = true;
  emit({ ev: "joined", at: now() });
  if (mode === "combat") await combatLoop({ bot, rcon, result, username, deadline, isEnded: () => ended });
  else await buildLoop({ bot, rcon, result, username, deadline, isEnded: () => ended, Vec3 });
  if (ended) result.notes.push(`disconnected: ${ended}`);
  try { bot.quit("stress done"); } catch { /* gone */ }
  if (rcon) rcon.close();
  await sleep(300);
