/**
 * SURVIVAL combat: setup over RCON (the gamemode reply must say Survival, else the run says so), then until the
 * deadline: a wave of hostile summons every COMBAT.waveSec (at most COMBAT.max in total), walk to the nearest foe and
 * hit it when the sword is recharged (~0.65 s). Counts hits given, damage taken, deaths (auto respawn) and kills.
 */
async function combatLoop({ bot, rcon, result, username, deadline, isEnded }) {
  if (!rcon) { result.notes.push("combat mode needs RCON for the survival setup; not run"); return; }
  for (const c of SL.combatSetup(username)) {
    try {
      const r = clip(L.stripColors(await rcon.command(c, 8000)), 160);
      if (c.startsWith("gamemode")) result.gamemode = /survival/i.test(r) ? "survival" : `unexpected reply: ${r}`;
    } catch (e) { result.setupFailed++; if (result.notes.length < 8) result.notes.push(`setup '${c.split(" ")[0]}': ${clip(e.message, 120)}`); }
  }
  if (result.gamemode !== "survival" && bot.game && bot.game.gameMode === "survival") result.gamemode = "survival";
  let lastHit = null, lastSwing = 0, wave = 0, lastWave = 0;
  let lastHealth = bot.health;
  bot.on("health", () => { if (bot.health < lastHealth - 0.01) result.hurt++; lastHealth = bot.health; });
  bot.on("death", () => { result.deaths++; });
  bot.on("entityDead", (e) => { if (e && e.name && !SL.NOT_A_FOE.has(e.name) && lastHit && lastHit.id === e.id) result.kills++; });
  await sleep(600);
  try { const sword = bot.inventory.items().find((i) => i.name === "iron_sword"); if (sword) await within(bot.equip(sword, "hand"), 3000); } catch (e) { result.notes.push(`equip: ${clip(e.message, 100)}`); }
  while (now() < deadline && !isEnded()) {
    try {
      if (now() - lastWave > SL.COMBAT.waveSec * 1000 && result.summoned < SL.COMBAT.max) {
        lastWave = now();
        const p = bot.entity.position;
        for (const c of SL.combatWave({ x: p.x, y: p.y, z: p.z }, wave++, SL.COMBAT.max - result.summoned)) { await rcon.command(c, 8000); result.summoned++; }
      }
      const foe = SL.pickFoe(Object.values(bot.entities), bot.entity.position);
      if (!foe) { bot.clearControlStates(); await sleep(250); continue; }
      await within(bot.lookAt(foe.position.offset(0, (foe.height || 1.6) * 0.8, 0), true), 1000);
      const d = bot.entity.position.distanceTo(foe.position);
      bot.setControlState("forward", d > 2.6);
      bot.setControlState("jump", d > 2.6 && !!bot.entity.isCollidedHorizontally);
      if (d <= 3.2 && now() - lastSwing >= 650) { bot.attack(foe); lastSwing = now(); lastHit = foe; result.attacks++; }
      await sleep(100);
    } catch (e) {
      result.failed++;
      if (result.notes.length < 8) result.notes.push(`action: ${clip(e && e.message, 120)}`);
      await sleep(300);
    }
  }
  try { bot.clearControlStates(); } catch { /* gone */ }
}

