package dev.nxeon.plugins.chunkmirror;

import java.util.BitSet;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import org.bukkit.Chunk;
import org.bukkit.NamespacedKey;
import org.bukkit.World;
import org.bukkit.block.Block;
import org.bukkit.persistence.PersistentDataContainer;
import org.bukkit.persistence.PersistentDataType;

/**
 * Remembers which blocks are mirrored COPIES (placed by the mirror, not by a player), so breaking one can be made
 * drop-free. The set lives in each chunk's PersistentDataContainer as one bitmap (one bit per block position), so it is
 * saved with the chunk and survives restarts. Size is bounded by construction: a chunk with 384 build layers needs at
 * most 384 * 256 bits = 12 KB, and only chunks that actually hold copies carry the key at all. While a chunk is
 * loaded the bitmap is cached in memory and written back to the chunk (once a second, on unload, on shutdown).
 * Main thread only.
 */
final class CopyTracker {
   private final NamespacedKey key;
   private final Map<ChunkId, Entry> cache = new HashMap<>();

   private static final class Entry {
      BitSet bits;
      boolean dirty;
   }

   CopyTracker(NamespacedKey key) {
      this.key = key;
   }

   private static int index(World world, int x, int y, int z) {
      return (y - world.getMinHeight() << 8) | (z & 15) << 4 | (x & 15);
   }

   private Entry entry(World world, int cx, int cz) {
      ChunkId id = new ChunkId(world.getUID(), cx, cz);
      Entry e = this.cache.get(id);
      if (e != null) {
         return e;
      }
      if (!world.isChunkLoaded(cx, cz)) {
         return null;
      }
      e = new Entry();
      byte[] raw = world.getChunkAt(cx, cz, false).getPersistentDataContainer().get(this.key, PersistentDataType.BYTE_ARRAY);
      e.bits = raw == null ? new BitSet() : BitSet.valueOf(raw);
      this.cache.put(id, e);
      return e;
   }

   /** True when the position carries a copy mark, whatever is in the block now (used to catch item drops). */
   boolean isMarked(Block b) {
      Entry e = this.entry(b.getWorld(), b.getX() >> 4, b.getZ() >> 4);
      return e != null && e.bits.get(index(b.getWorld(), b.getX(), b.getY(), b.getZ()));
   }

   /** True when the block is a live mirrored copy. A mark on an empty cell is stale and is cleared on the spot. */
   boolean isCopy(Block b) {
      Entry e = this.entry(b.getWorld(), b.getX() >> 4, b.getZ() >> 4);
      if (e == null) {
         return false;
      }
      int i = index(b.getWorld(), b.getX(), b.getY(), b.getZ());
      if (!e.bits.get(i)) {
         return false;
      }
      if (b.isEmpty()) {
         e.bits.clear(i);
         e.dirty = true;
         return false;
      }
      return true;
   }

   void mark(Block b) {
      Entry e = this.entry(b.getWorld(), b.getX() >> 4, b.getZ() >> 4);
      if (e != null) {
         int i = index(b.getWorld(), b.getX(), b.getY(), b.getZ());
         if (!e.bits.get(i)) {
            e.bits.set(i);
            e.dirty = true;
         }
      }
   }

   void unmark(Block b) {
      Entry e = this.entry(b.getWorld(), b.getX() >> 4, b.getZ() >> 4);
      if (e != null) {
         int i = index(b.getWorld(), b.getX(), b.getY(), b.getZ());
         if (e.bits.get(i)) {
            e.bits.clear(i);
            e.dirty = true;
         }
      }
   }

   /** Moves a mark with a block (piston push/pull) so a moved copy stays drop-free. */
   void move(Block from, Block to) {
      if (this.isMarked(from)) {
         this.unmark(from);
         this.mark(to);
      }
   }

   /** Writes one chunk's bitmap into the chunk and forgets it. Called from ChunkUnloadEvent. */
   void unload(Chunk chunk) {
      ChunkId id = new ChunkId(chunk.getWorld().getUID(), chunk.getX(), chunk.getZ());
      Entry e = this.cache.remove(id);
      if (e != null && e.dirty) {
         this.write(chunk, e);
      }
   }

   private void write(Chunk chunk, Entry e) {
      PersistentDataContainer pdc = chunk.getPersistentDataContainer();
      if (e.bits.isEmpty()) {
         pdc.remove(this.key);
      } else {
         pdc.set(this.key, PersistentDataType.BYTE_ARRAY, e.bits.toByteArray());
      }
      e.dirty = false;
   }

   /** Writes every changed bitmap of loaded chunks. Cheap when nothing changed. */
   void flush(Iterable<World> worlds) {
      Iterator<Map.Entry<ChunkId, Entry>> it = this.cache.entrySet().iterator();
      while (it.hasNext()) {
         Map.Entry<ChunkId, Entry> me = it.next();
         Entry e = me.getValue();
         if (!e.dirty) {
            continue;
         }
         ChunkId id = me.getKey();
         World w = null;
         for (World cand : worlds) {
            if (cand.getUID().equals(id.world())) {
               w = cand;
               break;
            }
         }
         if (w == null || !w.isChunkLoaded(id.x(), id.z())) {
            it.remove();
            continue;
         }
         this.write(w.getChunkAt(id.x(), id.z(), false), e);
      }
   }

   boolean hasDirty() {
      for (Entry e : this.cache.values()) {
         if (e.dirty) {
            return true;
         }
      }
      return false;
   }

   /** Number of copy marks in currently loaded chunks (for /chunkmirror status). */
   long loadedCopyCount() {
      long n = 0;
      for (Entry e : this.cache.values()) {
         n += e.bits.cardinality();
      }
      return n;
   }

   int cachedChunks() {
      return this.cache.size();
   }
}
