import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.logging.Logger;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;
import org.bukkit.Bukkit;
import org.bukkit.Material;
import org.bukkit.block.data.BlockData;

/**
 * Block changes that could not be applied yet because the target chunk was not loaded. They are replayed once, when
 * that chunk loads, and then forgotten (the chunk file keeps the result), so a later change a player makes in that
 * chunk is never undone by a second replay. Bounded by chunk count and entry count (oldest chunk dropped first) and saved to
 * one compact gzip file. Main thread only.
 */
final class PendingLog {
   /** One pending change: the block state to set, and for a "matching" break the material that must still be there. */
   record Cell(BlockData data, Material match) {
   }

   private final LinkedHashMap<ChunkId, LinkedHashMap<Long, Cell>> map = new LinkedHashMap<>();
   private int total;
   private int maxChunks = 2000;
   private int maxEntries = 200000;
   private boolean dirty;

   void setLimits(int maxChunks, int maxEntries) {
      this.maxChunks = maxChunks;
      this.maxEntries = maxEntries;
      this.trim();
   }

   private static long cellKey(int relX, int y, int relZ) {
      return (long)(y + 2048) << 8 | (relZ & 15) << 4 | (relX & 15);
   }

   static int keyRelX(long k) {
      return (int)(k & 15L);
   }

   static int keyRelZ(long k) {
      return (int)(k >> 4 & 15L);
   }

   static int keyY(long k) {
      return (int)(k >> 8) - 2048;
   }

   void add(ChunkId id, int relX, int y, int relZ, Cell cell) {
      LinkedHashMap<Long, Cell> chunk = this.map.computeIfAbsent(id, k -> new LinkedHashMap<>());
      if (chunk.put(cellKey(relX, y, relZ), cell) == null) {
         this.total++;
      }
      this.dirty = true;
      this.trim();
   }

   private void trim() {
      while ((this.map.size() > this.maxChunks || this.total > this.maxEntries) && !this.map.isEmpty()) {
         Iterator<Map.Entry<ChunkId, LinkedHashMap<Long, Cell>>> it = this.map.entrySet().iterator();
         Map.Entry<ChunkId, LinkedHashMap<Long, Cell>> eldest = it.next();
         this.total -= eldest.getValue().size();
         it.remove();
         this.dirty = true;
      }
   }

   /** Removes and returns everything waiting for this chunk, or null. */
   Map<Long, Cell> take(ChunkId id) {
      LinkedHashMap<Long, Cell> got = this.map.remove(id);
      if (got == null) {
         return null;
      }
      this.total -= got.size();
      this.dirty = true;
      return got;
   }

   boolean has(ChunkId id) {
      return this.map.containsKey(id);
   }

   int totalEntries() {
      return this.total;
   }

   int chunkCount() {
      return this.map.size();
   }

   boolean isDirty() {
      return this.dirty;
   }

   void clear() {
      this.map.clear();
      this.total = 0;
      this.dirty = true;
   }

   // ---- persistence: gzip, DataOutputStream. magic, version, palette, chunks ----
   private static final int MAGIC = 0x434D5031; // "CMP1"

   void save(File file, Logger log) {
      try {
         File dir = file.getParentFile();
         if (!dir.exists()) {
            dir.mkdirs();
         }
         File tmp = new File(dir, file.getName() + ".tmp");
         Map<String, Integer> palette = new HashMap<>();
         List<String> paletteList = new ArrayList<>();
         try (DataOutputStream out = new DataOutputStream(new BufferedOutputStream(new GZIPOutputStream(Files.newOutputStream(tmp.toPath()))))) {
            for (LinkedHashMap<Long, Cell> chunk : this.map.values()) {
               for (Cell c : chunk.values()) {
                  String s = c.data().getAsString();
                  if (!palette.containsKey(s)) {
                     palette.put(s, paletteList.size());
                     paletteList.add(s);
                  }
               }
            }
            out.writeInt(MAGIC);
            out.writeInt(paletteList.size());
            for (String s : paletteList) {
               out.writeUTF(s);
            }
            out.writeInt(this.map.size());
            for (Map.Entry<ChunkId, LinkedHashMap<Long, Cell>> e : this.map.entrySet()) {
               out.writeLong(e.getKey().world().getMostSignificantBits());
               out.writeLong(e.getKey().world().getLeastSignificantBits());
               out.writeInt(e.getKey().x());
               out.writeInt(e.getKey().z());
               out.writeInt(e.getValue().size());
               for (Map.Entry<Long, Cell> ce : e.getValue().entrySet()) {
                  out.writeLong(ce.getKey());
                  out.writeInt(palette.get(ce.getValue().data().getAsString()));
