               int pi = in.readInt();
               String m = in.readUTF();
               if (pi >= 0 && pi < pn && palette[pi] != null) {
                  Material match = m.isEmpty() ? null : Material.matchMaterial(m);
                  cells.put(key, new Cell(palette[pi], match));
               }
            }
            if (!cells.isEmpty()) {
               this.map.put(id, cells);
               this.total += cells.size();
            }
         }
         this.trim();
         this.dirty = false;
      } catch (IOException | RuntimeException ex) {
         log.warning("Could not read " + file.getName() + " (" + ex + "); starting with an empty pending list.");
         File bad = new File(file.getParentFile(), file.getName() + ".corrupt");
         try {
            Files.move(file.toPath(), bad.toPath(), StandardCopyOption.REPLACE_EXISTING);
         } catch (IOException ignored) {
            // leave it in place
         }
         this.map.clear();
         this.total = 0;
      }
   }
}
